import sys,json,re; sys.path.insert(0,'/tmp/ss-build/tools/lesson-generators')
import os; os.chdir('/tmp/ss-build')
from kit2 import T
def slug(s): return re.sub(r'[^a-z0-9]+','-',s.lower()).strip('-')
def Q(topic,w1,w2):
    return ["m|This lesson is about|%s|building a bridge|cooking rice|Theme."%topic,"t|We should read the chapter before the lesson.|T|Yes.","m|A word to learn|%s|zebra|lorry|Word."%w1,"t|Every chapter has a theme or message.|T|Yes.","m|Another word to learn|%s|xylophone|jungle|Word."%w2,"s|Write one word to learn: %s.|%s|Word."%(w1,w1),"m|After reading we should|think and retell|forget it|skip it|Habit.","t|We can discuss the theme in our own words.|T|Yes."]
def build(cls,items):
    P='content/curriculum/cbse-2026-27.json'
    d=json.load(open(P))
    subj=[s for c in d['classes'] if c['classLevel']==cls for s in c['subjects'] if s['slug']=='english'][0]
    have={c['slug'] for c in subj['chapters']}
    for title,theme,w1,w2,w3 in items:
        if slug(title) not in have: subj['chapters'].append({"slug":slug(title),"name":{"en":title},"topics":[]})
    json.dump(d,open(P,'w'),ensure_ascii=False,indent=2)
    S=dict(cls=cls,subj="english",subj_file="english")
    for title,theme,w1,w2,w3 in items:
        en="Theme and words: "+title
        T(S,slug(title),"theme-and-vocabulary-"+slug(title)[:30],en,"A student read the chapter '%s' and shared what it taught.\n\"%s\""%(title,theme),
          ["Chapter: %s. %s"%(title,theme),"Read the chapter, then tell the main idea in your own words and give your opinion on it.","Words to learn: %s, %s, %s."%(w1,w2,w3)],[w1,w2,w3],
          ("What is the main idea of '%s'?"%title,[("Read the chapter.","Read."),("Say it in one sentence.","Say."),(theme,"Answer.")]),
          ("A chapter has no message.",["Every chapter has a theme.",theme],["Wrong."]),[theme,"Use new words in sentences."],Q(title,w1,w2))
